function cidrContains(cidr: string, ip: string): boolean {
  const [base, bits] = cidr.split("/");
  const mask = Number(bits) === 0 ? 0 : ~((1 << (32 - Number(bits))) - 1) >>> 0;
  return (toInt(base) & mask) === (toInt(ip) & mask);
}

